const b = $input.first().json.body || {};
const token = String(b.token || '');
const action = String(b.action || '');
if (!/^[a-f0-9]{64}$/.test(token)) return [{ json: { ok: false, error: 'session_invalide' } }];
if (['list', 'moderate', 'report_done', 'warn', 'suspend', 'exclude', 'lift'].indexOf(action) === -1) return [{ json: { ok: false, error: 'requete_invalide' } }];
const AUTH = "a.id=1 AND a.session_hash=SHA2('" + token + "',256) AND a.session_expires > NOW()";
let q0 = 'SELECT 1', q0b = 'SELECT 1', sanction = null;
if (action === 'moderate') {
  const cid = parseInt(b.cid, 10);
  const st = b.decision === 'approve' ? 'demande' : b.decision === 'reject' ? 'rejetee' : null;
  if (!Number.isInteger(cid) || cid < 1 || !st) return [{ json: { ok: false, error: 'requete_invalide' } }];
  q0 = "UPDATE conversations c JOIN admin_access a ON " + AUTH + " SET c.status='" + st + "' WHERE c.id=" + cid + " AND c.status='moderation'";
}
if (action === 'report_done') {
  const cid = parseInt(b.cid, 10);
  if (!Number.isInteger(cid) || cid < 1) return [{ json: { ok: false, error: 'requete_invalide' } }];
  q0 = "UPDATE member_reports r JOIN admin_access a ON " + AUTH + " SET r.status='traite' WHERE r.conversation_id=" + cid + " AND r.status='nouveau'";
}
if (['warn', 'suspend', 'exclude', 'lift'].indexOf(action) !== -1) {
  const mid = parseInt(b.member_id, 10);
  if (!Number.isInteger(mid) || mid < 1) return [{ json: { ok: false, error: 'requete_invalide' } }];
  let days = null;
  if (action === 'suspend') { days = parseInt(b.days, 10); if ([7, 30].indexOf(days) === -1) return [{ json: { ok: false, error: 'requete_invalide' } }]; }
  const SET = { warn: null,
    suspend: "m.status='suspendu', m.suspended_until=DATE_ADD(NOW(), INTERVAL " + days + " DAY), m.session_hash=NULL, m.session_expires=NULL",
    exclude: "m.status='exclu', m.suspended_until=NULL, m.session_hash=NULL, m.session_expires=NULL",
    lift: "m.status='actif', m.suspended_until=NULL" }[action];
  if (SET) q0 = "UPDATE members m JOIN admin_access a ON " + AUTH + " SET " + SET + " WHERE m.id=" + mid + (action === 'suspend' ? " AND m.status<>'exclu'" : "");
  q0b = "INSERT INTO member_sanctions (member_id, kind, days) SELECT m.id, '" + action + "', " + (days === null ? 'NULL' : days) + " FROM members m JOIN admin_access a ON " + AUTH + " WHERE m.id=" + mid;
  sanction = { action, member_id: mid, days };
}
const SANC = (x) => "(SELECT JSON_ARRAYAGG(JSON_OBJECT('type', s.kind, 'jours', s.days, 'date', DATE_FORMAT(s.created_at,'%Y-%m-%dT%H:%i'))) FROM member_sanctions s WHERE s.member_id=" + x + ")";
const q1 = "SELECT a.id AS admin_id, c.id AS cid, c.status, c.created_at AS cdate, ma.id AS a_id, ma.email AS a_email, ma.display_name AS a_nom, ma.gender AS a_genre, mb.id AS b_id, mb.email AS b_email, mb.display_name AS b_nom, mb.gender AS b_genre, ma.status AS a_statut, DATE_FORMAT(ma.suspended_until,'%d.%m.%Y') AS a_fin, mb.status AS b_statut, DATE_FORMAT(mb.suspended_until,'%d.%m.%Y') AS b_fin, " + SANC('ma.id') + " AS a_sanctions, " + SANC('mb.id') + " AS b_sanctions, (SELECT JSON_ARRAYAGG(JSON_OBJECT('id', r.id, 'par', r.reporter_id, 'motif', r.reason, 'details', r.details, 'date', DATE_FORMAT(r.created_at,'%Y-%m-%dT%H:%i'), 'statut', r.status, 'contre', r.reported_id)) FROM member_reports r WHERE r.conversation_id=c.id) AS rapports, m.id AS mid, m.sender_id, m.body, m.created_at AS mdate " +
  "FROM (SELECT 1 AS x) d LEFT JOIN admin_access a ON " + AUTH + " LEFT JOIN conversations c ON a.id IS NOT NULL LEFT JOIN members ma ON ma.id=c.member_a LEFT JOIN members mb ON mb.id=c.member_b LEFT JOIN messages m ON m.conversation_id=c.id " +
  "ORDER BY (c.status='moderation') DESC, (SELECT COUNT(*) FROM member_reports r2 WHERE r2.conversation_id=c.id AND r2.status='nouveau') DESC, c.id DESC, m.id ASC LIMIT 1000";
return [{ json: { ok: true, q0, q0b, q1, sanction } }];

const rows = $input.all().map(i => i.json);
if (!rows.length || rows[0].admin_id === null || rows[0].admin_id === undefined) return [{ json: { success: false, error: 'session_invalide' } }];
const map = new Map();
for (const r of rows) {
  if (r.cid === null || r.cid === undefined) continue;
  if (!map.has(r.cid)) map.set(r.cid, {
    cid: r.cid, statut: r.status, date: r.cdate,
    a: { id: r.a_id, email: r.a_email, nom: r.a_nom, genre: r.a_genre, statut: r.a_statut, fin: r.a_fin, sanctions: (function (x) { try { const v = typeof x === 'string' ? JSON.parse(x) : x; return Array.isArray(v) ? v : []; } catch (e) { return []; } })(r.a_sanctions) },
    b: { id: r.b_id, email: r.b_email, nom: r.b_nom, genre: r.b_genre, statut: r.b_statut, fin: r.b_fin, sanctions: (function (x) { try { const v = typeof x === 'string' ? JSON.parse(x) : x; return Array.isArray(v) ? v : []; } catch (e) { return []; } })(r.b_sanctions) }, messages: [],
    signalements: (function (x) { try { const v = typeof x === 'string' ? JSON.parse(x) : x; return Array.isArray(v) ? v : []; } catch (e) { return []; } })(r.rapports)
  });
  if (r.mid !== null && r.mid !== undefined) map.get(r.cid).messages.push({ id: r.mid, de_a: Number(r.sender_id) === Number(r.a_id), texte: r.body, date: r.mdate });
}
const conversations = Array.from(map.values());
// E-mail au membre sanctionné
let _mail = null;
const sc = $('Prepare').first().json.sanction;
if (sc && sc.action !== 'lift') {
  let cible = null;
  for (const c of conversations) { if (Number(c.a.id) === sc.member_id) cible = c.a; else if (Number(c.b.id) === sc.member_id) cible = c.b; if (cible) break; }
  if (cible && cible.email) {
    const pied = '\n\nSi vous souhaitez vous expliquer, vous pouvez répondre par écrit à cet e-mail.\n\nNikah — modération';
    const fin = new Date(Date.now() + (sc.days || 0) * 86400000);
    const finTxt = ('0' + fin.getDate()).slice(-2) + '.' + ('0' + (fin.getMonth() + 1)).slice(-2) + '.' + fin.getFullYear();
    const T = {
      warn: ['Nikah — avertissement', "Bonjour,\n\nL'équipe de modération de Nikah a été informée d'un comportement contraire à la charte de la plateforme dans l'une de vos conversations.\n\nCeci est un avertissement. Les échanges doivent rester respectueux, sérieux et tournés vers le mariage. Les propos déplacés, l'insistance, les demandes d'argent et les demandes de coordonnées hors du site sont interdits.\n\nEn cas de récidive, votre compte pourra être suspendu ou fermé."],
      suspend: ['Nikah — suspension de votre compte', "Bonjour,\n\nÀ la suite d'un signalement, et après lecture de la conversation concernée, votre compte Nikah est suspendu pendant " + sc.days + " jours, jusqu'au " + finTxt + ".\n\nPendant cette période, vous ne pouvez plus vous connecter et votre profil n'apparaît plus dans les recherches. Votre compte sera rétabli automatiquement à la fin de la suspension.\n\nEn cas de nouveau manquement à la charte, votre compte pourra être fermé définitivement."],
      exclude: ['Nikah — fermeture de votre compte', "Bonjour,\n\nÀ la suite d'un signalement, et après lecture de la conversation concernée, votre compte Nikah a été fermé définitivement pour un manquement grave à la charte de la plateforme.\n\nVous ne pouvez plus vous connecter et votre profil n'est plus visible."]
    }[sc.action];
    if (T) _mail = { to: cible.email, subject: T[0], text: T[1] + pied };
  }
}
return [{ json: { _mail, success: true, a_traiter: conversations.filter(c => c.signalements.some(s => s.statut === 'nouveau')).length, a_moderer: conversations.filter(c => c.statut === 'moderation').length, conversations } }];
